create table public.optimizer_profiles (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),external_id text not null,email text not null check(email ~ '^[a-z0-9-]+@fixture\.example$'),consent text not null check(consent in ('subscribed','unsubscribed','pending')),last_engaged_at timestamptz,last_order_at timestamptz,hard_bounce boolean not null default false,spam boolean not null default false,suppression_reasons text[] not null default '{}' check(suppression_reasons<@array['optimizer','consent','hard_bounce','spam','manual','provider']::text[]),fixture_responds boolean not null default false,revision integer not null default 1,synthetic boolean not null default true check(synthetic),created_at timestamptz not null default now(),unique(tenant_id,external_id),unique(tenant_id,id)
);
create table public.optimizer_sweeps (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),revision integer not null default 1,state text not null default 'preview' check(state in ('preview','approved','winback_wait','completed')),observed_at timestamptz not null,snapshot jsonb not null,pricing_snapshot jsonb not null,expires_at timestamptz not null default now()+interval '30 minutes',approved_by uuid references public.profiles(id),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(tenant_id,id)
);
create table public.optimizer_candidates (
 sweep_id uuid not null references public.optimizer_sweeps(id),tenant_id uuid not null,profile_id uuid not null,profile_revision integer not null,eligible boolean not null,reason text not null,state text not null default 'preview' check(state in ('preview','excluded','winback_1','winback_2','recovered','suppressed','skipped')),updated_at timestamptz not null default now(),primary key(sweep_id,profile_id),foreign key(tenant_id,profile_id) references public.optimizer_profiles(tenant_id,id)
);
create table public.optimizer_events (
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,profile_id uuid not null,sweep_id uuid references public.optimizer_sweeps(id),kind text not null check(kind in ('winback_1','winback_2','recovered','suppressed','skipped','reversed','profile_evidence_changed')),detail jsonb not null,created_at timestamptz not null default now(),foreign key(tenant_id,profile_id) references public.optimizer_profiles(tenant_id,id)
);
create unique index optimizer_once_per_stage on public.optimizer_events(sweep_id,profile_id,kind) where sweep_id is not null;
do $$declare tab text;begin foreach tab in array array['optimizer_profiles','optimizer_sweeps','optimizer_candidates','optimizer_events'] loop execute format('alter table public.%I enable row level security',tab);execute format('create policy tenant_read on public.%I for select to authenticated using(private.is_active_member(tenant_id,array[''owner'',''admin'']::public.tenant_role[]))',tab);execute format('grant select on public.%I to authenticated',tab);end loop;end $$;
